def preflight(conn, limit=20):
    if not 1 <= limit <= 100:
        raise ValueError('PREFLIGHT_LIMIT_INVALID')
    problems=[]
    for table, predicate in CHECKS:
        count=conn.execute(text("SELECT count(*) FROM "+table+" r WHERE NOT ("+predicate+")")).scalar_one()
        if count:
            ident="export_id" if table.endswith("_snapshot_rows") else "id"
            ids=conn.execute(text("SELECT "+ident+" FROM "+table+" r WHERE NOT ("+predicate+") LIMIT :limit"),{'limit':limit}).scalars().all()
            problems.append({'table':table,'count':count,'sample_internal_ids':ids})
    return {'ok':not problems,'problems':problems}


def require_clean(conn):
    report=preflight(conn)
    if not report['ok']:
        raise RuntimeError('SELF_CERTIFICATE_OWNER_CHAIN_PREFLIGHT_FAILED:'+','.join(p['table'] for p in report['problems']))
    return report


def ensure_sqlite_owner_chain(engine):
    if engine.dialect.name!='sqlite':
        return
    with engine.begin() as conn:
        require_clean(conn)
        for statement in SQLITE_GUARDS:
            conn.exec_driver_sql(statement)
